`timescale 1ns/1ps
// @latency 3
module signed_fir4 (
    input wire clk,
    input wire rst,
    input wire signed [7:0] x,
    input wire in_valid,
    output wire in_ready,
    output wire signed [12:0] out_data,
    output wire out_valid,
    input wire out_ready
);
    reg signed [7:0] x1;
    reg signed [7:0] x2;
    reg signed [7:0] x3;

    reg v1;
    reg v2;
    reg v3_out;
    (* KEEP = "TRUE" *) reg v3_ready;

    reg signed [12:0] d1;
    reg signed [12:0] d2;
    reg signed [12:0] d3;

    wire r3 = !v3_ready || out_ready;
    wire r2 = !v2 || r3;
    wire r1 = !v1 || r2;

    assign in_ready = r1;
    assign out_valid = v3_out;
    assign out_data = d3;

